function catalogLicenseOverlay(item){
 if(!item||typeof item!=='object'||(item.weights_license!==null&&item.weights_license!==undefined&&item.weights_license!=='')||item.urls?.weights_license)return null;
 const review=catalogLicenseReviews.find(r=>Object.entries(r.guard).every(([key,value])=>item[key]===value));
 if(!review||!Array.isArray(item.sources))return null;
 const actual=[...new Set(item.sources.map(s=>s?.url))].sort();
 if(JSON.stringify(actual)!==JSON.stringify([...review.source_urls].sort()))return null;
 // Return a fresh projection: a consumer cannot mutate future evidence or canonical input.
 return JSON.parse(JSON.stringify(review));
}
function catalogLicenseEvidenceDOM(item,doc=document){
 const review=catalogLicenseOverlay(item);if(!review)return null;
 const make=(tag,value)=>{const e=doc.createElement(tag);if(value!==undefined)e.textContent=value;return e;};
 const section=make('section');section.className='catalog-license-evidence';
 section.setAttribute('aria-label','权重许可补充核验');
 section.append(make('h3','权重许可补充核验'),make('p','许可声明：'+review.license_name),make('p','适用检查点：'+review.checkpoint));
 section.append(make('p',review.declaration_status+'；'+review.text_status+'。'),make('p','本项核验：'+review.checked_at+'（不是发布日期；不替换原记录核验日）。'),make('p',review.scope_note));
 section.append(make('p','公开文件列表可读；未下载或运行，下载时的访问门槛未验证。来源 main 可更新，未锁定不可变权重哈希；使用前请重核当前条款。'));
 const links=make('p');for(const entry of review.links){const url=safeURL(entry.url);if(!url||!url.startsWith('https:'))continue;const a=make('a',entry.label);a.href=url;a.target='_blank';a.rel='noopener noreferrer';links.append(a,make('span',' · '));}section.append(links);
 section.append(make('p','这是一项有范围的来源核对，不自动证明开源，也不构成具体用途的法律许可。'));return section;
}

