 const meta=make('dl');for(const [key,value] of [['适用版本 / 记录快照',model.version],['来源核验日期（不是发布日期）',model.checked_at]])meta.append(make('dt',key),make('dd',value));box.append(meta);
 const columns=make('div');columns.className='reference-access-groups';
 for(const [key,title] of [['papers','论文与技术报告'],['official',options.catalog?'文档与代码入口':'官方资料与代码'],['other','其他登记来源']]){
  const rows=model.groups[key];if(key==='other'&&!rows.length)continue;const group=make('div');group.append(make('h5',title));
  if(!rows.length)group.append(make('p','未登记可直接打开的入口；不代表该资料不存在。'));
  else {const list=make('ul');for(const row of rows.slice(0,3)){const li=make('li'),a=make('a',row.title+' ↗');a.href=row.url;a.target='_blank';a.rel='noopener noreferrer';li.append(a);if(row.checked_at)li.append(make('small','该来源核验：'+row.checked_at));list.append(li);}group.append(list);if(rows.length>3)group.append(make('p','另有 '+(rows.length-3)+' 条，见下方全部来源。'));}columns.append(group);
 }
 const overlay=options.catalog===true?catalogResourceOverlay(item):null;if(overlay)box.append(make('p',overlay.note));
 box.append(columns,make('p','入口沿用登记记录，不表示当前可访问、论文已完整读过或产品已实测。链接页面可能更新，请核对记录版本。原始核验范围与未知项请一起阅读。'));
